Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Ellos están en la guía recta de su Señor, y ellos son los triunfadores. 2:5; 31:5
- = ¡Oh, hijos de Israel! Recordad Mi gracia que os concedí y que os preferí a todos los pueblos (mundos). 2:47; 2:122
- = Esa fue una comunidad que ya pasó. Tendrá lo que se ganó, y vosotros tendréis lo que os ganéis. Y no seréis interrogados por lo que ellos solían hacer. 2:134; 2:141
- = Eternamente allí permanecerán; el castigo no se les aliviará ni se les dará respiro. 2:162; 3:88
- = Excepto aquellos que, después de eso, se arrepientan y se corrijan. En verdad, Al-lah es Indulgente, Misericordioso. 3:89; 24:5
- = Y quienes no creen y desmienten Nuestras señales – esos son los compañeros del Infierno. 5:10; 5:86
- = Y no les llega ninguna señal de las señales de su Señor, sino que se apartan de ella. 6:4; 36:46
- = Y antes de ti, los mensajeros fueron ridiculizados, pero aquellos que se burlaban fueron envueltos por aquello de lo que se burlaban. 6:10; 21:41
- = Di: "Temo, si desobedezco a mi Señor, el castigo de un día terrible." 6:15; 39:13
- = Entonces el terremoto los sorprendió, y amanecieron en sus casas, muertos y caídos de bruces. 7:78; 7:91
- = Y arrojó su vara, y he aquí que era una serpiente manifiesta. 7:107; 26:32
- = Y extrajo su mano, y he aquí que era blanca (resplandeciente) para quienes miraban. 7:108; 26:33
- = Dijeron: "Creemos en el Señor de los mundos." 7:121; 26:47
- = El Señor de Moisés y de Aarón. 7:122; 26:48
- = Y les daré plazo. En verdad, Mi plan es firme. 7:183; 68:45
- = Él es Quien envió a Su Mensajero con la guía y la religión de la verdad, para hacerla prevalecer sobre todas las religiones, aunque los politeístas lo detesten. 9:33; 61:9
- = ¡Oh, Profeta! Combate a los incrédulos y a los hipócritas, y sé severo con ellos. Su morada será el Infierno, ¡y qué mal destino! 9:73; 66:9
- = Y dicen: "¿Cuándo se cumplirá esta promesa, si sois veraces?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Y enviamos a Moisés con Nuestras señales y con autoridad evidente. 11:96; 40:23
- = Y dimos a Moisés la Escritura, pero se discrepó sobre ella. Y si no fuera por una palabra anterior de tu Señor, se habría juzgado entre ellos. Y ellos están en duda sobre ella. 11:110; 41:45
- = Eso no es difícil para Al-lah. 14:20; 35:17
- = "Y cuando lo haya modelado y haya insuflado en él de Mi espíritu, postraos ante él." 15:29; 38:72
- = Y los ángeles se postraron todos juntos. 15:30; 38:73
- = (Al-lah) dijo: "Entonces sal de él, pues eres maldito." 15:34; 38:77
- = (Iblis) dijo: "¡Señor mío! Concédeme un plazo hasta el día en que sean resucitados." 15:36; 38:79
- = (Al-lah) dijo: "Serás de aquellos a quienes se les concede un plazo." 15:37; 38:80
- = Hasta el día del tiempo conocido." 15:38; 38:81
- = Excepto Tus siervos sinceros entre ellos. 15:40; 38:83
- = Los piadosos estarán en jardines y manantiales. 15:45; 51:15
- = (Abraham) dijo: "¿Cuál es vuestro asunto, oh mensajeros?" 15:57; 51:31
- = Dijeron: "Hemos sido enviados a un pueblo de criminales." 15:58; 51:32
- = Quienes creen y no confunden su fe con la injusticia – esos tendrán seguridad, y ellos son los bien guiados. 16:42; 29:59
- = Para que nieguen lo que les hemos dado. Disfrutad, pues pronto sabréis. 16:55; 30:34
- = Luego siguió un camino. 18:89; 18:92
- = Ve al Faraón, pues él se ha excedido. 20:24; 79:17
- = Y quienes guardan sus partes íntimas. 23:5; 70:29
- = Excepto con sus esposas o con lo que poseen sus diestras – pues no son censurables. 23:6; 70:30
- = Y quienes buscan más allá de eso, esos son los transgresores. 23:7; 70:31
- = Y quienes cumplen con sus depósitos y sus promesas. 23:8; 70:32
- = (Noé) dijo: "¡Señor mío! Auxíliame, porque me han desmentido." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = Estos son los versículos de la Escritura clara. 26:2; 28:2
- = En esto hay, en verdad, una señal, pero la mayoría de ellos no cree. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = Y en verdad, tu Señor – Él es el Poderoso, el Misericordioso. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = Y ahogamos a los otros. 26:66; 37:82
- = En verdad, yo soy para vosotros un mensajero digno de confianza. 26:107; 26:125; 26:143; 26:162; 26:178
- = Temed, pues, a Al-lah y obedecedme. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = Y no os pido recompensa por ello; mi recompensa es solo del Señor de los mundos. 26:109; 26:127; 26:145; 26:164; 26:180
- = En jardines y manantiales. 26:147; 44:52
- = Dijeron: "Eres solo uno de los hechizados." 26:153; 26:185
- = Excepto su esposa – decretamos que ella fuera de los que se quedaron atrás. 26:171; 37:135
- = Luego destruimos a los otros. 26:172; 37:136
- = E hicimos llover sobre ellos una lluvia (de piedras), ¡y qué lluvia tan mala para los advertidos! 26:173; 27:58
