- Un fuego, y dijo a su familia: "Quedaos, he divisado un fuego; quizá os traiga de él." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
