- Y dicen: "¿Por qué no ha sido revelada una señal de su Señor?" Di: "En verdad." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
