- Se apartó de ellos y dijo: "¡Oh, pueblo mío! Ciertamente os he transmitido el mensaje de mi Señor y os he aconsejado bien." (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- Debajo de ellos corren ríos; serán adornados en ellos con brazaletes de oro. (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
