- Te ha llegado del conocimiento; no tienes de Alá ningún protector ni. (جَاءَكَ مِنَ الْعِلْمِ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا) 2:120; 13:37
